        // Deposit Ether into c to give the test contract a nonzero balance.
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk);

        // Read the caller's balance before withdrawing.
        uint256 balBefore = c.balances(address(this));

        bool reverted;
