contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance");

        // Create the state the rule needs: the caller's balance in c is exactly depositAmount.
        c.fallback{value: depositAmount}();

        uint256 cBalanceBefore = address(c).balance;
        uint256 testBalanceBefore = address(this).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(
                c.balances(address(this)) == 0 &&
                address(c).balance == cBalanceBefore - depositAmount &&
                address(this).balance == testBalanceBefore + depositAmount
            );
        } else {
            assert(
                c.balances(address(this)) == depositAmount &&
                address(c).balance == cBalanceBefore &&
                address(this).balance == testBalanceBefore
            );
        }
    }
}

