contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance");

        // Record balances before making any changes.
        uint256 cBalanceBefore = address(c).balance;
        uint256 testBalanceBefore = address(this).balance;

        // Deposit via the payable fallback; this is a top-level state-changing call.
        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the withdraw call must either clear the caller's balance
        // and transfer back exactly the deposited amount, or revert and leave
        // everything untouched.
        assert(
            (!reverted &&
                c.balances(address(this)) == 0 &&
                address(c).balance == cBalanceBefore &&
                address(this).balance == testBalanceBefore) ||
            (reverted &&
                c.balances(address(this)) == depositAmount &&
                address(c).balance == cBalanceBefore + depositAmount &&
                address(this).balance == testBalanceBefore - depositAmount)
        );
    }
}

