    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 extraAmount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount + extraAmount);

        c.fallback{value: amount + extraAmount}();

        uint256 beforeBal = c.balances(address(this));

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.balances(address(this));
        assert(reverted ? afterBal == beforeBal : afterBal == 0);
    }

    receive() external payable {}
}

