contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    fallback() external payable {
        assembly { calldatacopy(0, 0, calldatasize()) }
        (bool s, ) = address(c).call{value: msg.value}("");
        require(s);
        assembly { returndatacopy(0, 0, returndatasize()) return(0, returndatasize()) }
    }

    function run(uint256 depositAmount) public payable {
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "insufficient balance");

        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        uint256 balBefore = c.balances(address(this));
        uint256 cEthBefore = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balances(address(this));
        uint256 cEthAfter = address(c).balance;

        assert(
            !reverted && balBefore == depositAmount && balAfter == 0 && cEthBefore >= depositAmount && cEthBefore - cEthAfter == depositAmount
