contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint deposit) public payable {
        require(address(this).balance >= deposit);

        // Fund the caller's balance in c via the fallback.
        (bool depositOk, ) = address(c).call{value: deposit}("");
        require(depositOk);

        uint256 beforeCaller = c.balances(address(this));
        uint256 beforeContract = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCaller = c.balances(address(this));
        uint256 afterContract = address(c).balance;

        // General rule: after a successful withdraw by the caller, the caller's
        // recorded balance becomes zero, and c's Ether balance decreases by
        // exactly the caller's pre-withdraw recorded balance.
        assert(
            reverted
                ? (afterCaller == beforeCaller && afterContract == beforeContract)
                : (afterCaller == 0 &&
                    beforeContract >= beforeCaller &&
                    afterContract == beforeContract - beforeCaller)
        );
    }
}

